}

func NewGermanLightStemmerFilter() *GermanLightStemmerFilter {
	return &GermanLightStemmerFilter{}
}

func (s *GermanLightStemmerFilter) Filter(input analysis.TokenStream) analysis.TokenStream {
	for _, token := range input {
